        moves: [...E, 'exd5', 'Bd6', 'Nc3', 'Nf6', 'Bc4', 'e4', 'Nd4', 'O-O', 'O-O', 'Bxh2+', 'Kxh2', 'Ng4+', 'Kg1', 'Qh4'],
        theoryTo: 18, sources: ['rcaElephant', 'elephantQC'],
